package mz.bam.seeky.android;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,qualifiers="w360dp-h800dp-mdpi",shadows={ReferenceDesign5150Test.LocalStorage.class}) @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class ReaderContrast5152Test {
 @Test public void realLibraryFiltersKeepDarkLabelsOnLightFields()throws Exception{ReferenceDesign5150Test f=new ReferenceDesign5150Test();f.before();try{f.a.books.filters();shadowOf(Looper.getMainLooper()).idle();UiDialog dialog=(UiDialog)ShadowDialog.getLatestDialog();f.capture(dialog.root,"organizar-claro-5152",336,670);List<ChoiceSpinner> choices=new ArrayList<>();collect(dialog.root,choices);assertEquals("disposição, madeira da estante e tipo",3,choices.size());for(ChoiceSpinner choice:choices){assertNotNull(choice.getSelectedView());assertEquals(AppPalette.of(f.a).ink,((TextView)choice.getSelectedView()).getCurrentTextColor());}choices.get(0).setSelection(2);choices.get(1).setSelection(2);shadowOf(Looper.getMainLooper()).idle();f.capture(dialog.root,"organizar-claro-5152",336,670);for(ChoiceSpinner choice:choices)assertEquals(AppPalette.of(f.a).ink,((TextView)choice.getSelectedView()).getCurrentTextColor());assertVisibleChecks(dialog.root,AppPalette.of(f.a));dialog.dismiss();}finally{f.after();}}
 void assertVisibleChecks(View v,AppPalette p){if(v instanceof CheckBox||v instanceof RadioButton){android.content.res.ColorStateList tint=((CompoundButton)v).getButtonTintList();assertNotNull(tint);assertEquals(p.muted,tint.getColorForState(new int[]{},0));assertEquals(p.accent,tint.getColorForState(new int[]{android.R.attr.state_checked},0));}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)assertVisibleChecks(g.getChildAt(i),p);}}
 void collect(View v,List<ChoiceSpinner> out){if(v instanceof ChoiceSpinner)out.add((ChoiceSpinner)v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount();n++)collect(g.getChildAt(n),out);}}
}
